def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            base = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] != bg:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            patch = [[base]*(c1-c0+1) for _ in range(r1-r0+1)]
            for y,x in cells:
                patch[y-r0][x-c0] = grid[y][x]
            objects.append((base, patch))
    base, out = objects[0]
    for _, patch in objects[1:]:
        for r in range(len(out)):
            for c in range(len(out[0])):
                if patch[r][c] != base:
                    out[r][c] = patch[r][c]
    return out
